// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    function testFuzz_property(uint256 value, uint256 timestamp, uint256 blockNumber) public {
        // Bound timestamp to be greater than 0 to make require(block.timestamp > pastBlockTime) possible
        timestamp = bound(timestamp, 1, type(uint256).max);
        // Ensure value is not 10 ether for our test case
        vm.assume(value != 10 ether);

        // Set block parameters
        vm.warp(timestamp);
        vm.roll(blockNumber % 1000);

        // Store initial pastBlockTime
        uint256 initialPastBlockTime = c.pastBlockTime();

        // Send value that is not 10 ether
        (bool success, ) = address(c).call{value: value}("");

        // The rule: if msg.value != 10 ether, pastBlockTime should NOT change
        assertTrue(!success || c.pastBlockTime() == initialPastBlockTime);
    }
}

